def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    remaining = 100 - n
    if remaining <= 1:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = op.count('C')
    op_d = n - op_c

    if op_c == 0:
        return 'D'

    if n >= 6 and op_d >= n - 1:
        return 'D'
    if n >= 12 and op_d >= n - 2:
        return 'D'

    recent = op[-10:] if n >= 10 else op
    rr = len(recent)
    rd = recent.count('D')
    if rr >= 5 and rd >= rr - 1:
        return 'D'
    if rr >= 8 and rd >= 6:
        return 'D'

    last_my = my[-1]
    last_op = op[-1]

    forgiven = 0
    punished = 0
    for i in range(1, n):
        if my[i - 1] == 'D':
            if op[i] == 'C':
                forgiven += 1
            else:
                punished += 1

    cooperative = op_c * 5 >= n * 4
    exploitable = cooperative and punished == 0 and forgiven >= 1

    def_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            def_streak += 1
        else:
            break

    if last_op == 'D':
        if def_streak >= 3 or op_d * 5 >= n * 3:
            return 'D'

        if def_streak == 2:
            if last_my == 'D' and cooperative:
                return 'C'
            return 'D'

        if last_my == 'D':
            return 'C' if op_c * 5 >= n * 3 else 'D'

        if n >= 2 and my[-2] == 'D' and cooperative:
            return 'C'

        return 'D'

    if exploitable:
        return 'D'

    if last_my == 'D':
        return 'C'

    if cooperative and op_d <= max(1, n // 10):
        if remaining <= 5 and rng.random() < 0.08:
            return 'D'
        if remaining <= 2 and op_d == 0 and n >= 50 and rng.random() < 0.04:
            return 'D'

    return 'C'
